-- CTE: recursive | salesdb

-- The numbers 1 to 10, generated by a recursive CTE (the WHERE is the break condition)
WITH RECURSIVE series AS (
    SELECT 1 AS n
    UNION ALL
    SELECT n + 1 FROM series WHERE n < 10
)
SELECT n FROM series;

-- The organisation chart: each employee with their level below the top manager
WITH RECURSIVE org AS (
    SELECT employeeid, firstname, managerid, 1 AS level
    FROM sales.employees
    WHERE managerid IS NULL
    UNION ALL
    SELECT e.employeeid, e.firstname, e.managerid, o.level + 1
    FROM sales.employees AS e
    INNER JOIN org AS o ON e.managerid = o.employeeid
)
SELECT employeeid, firstname, managerid, level
FROM org
ORDER BY level, employeeid;

-- The reporting chain for each employee, from the top manager down to them
WITH RECURSIVE chain AS (
    SELECT employeeid, firstname::text AS path, 1 AS level
    FROM sales.employees
    WHERE managerid IS NULL
    UNION ALL
    SELECT e.employeeid, c.path || ' > ' || e.firstname, c.level + 1
    FROM sales.employees AS e
    INNER JOIN chain AS c ON e.managerid = c.employeeid
)
SELECT employeeid, path, level
FROM chain
ORDER BY path;

-- Everyone who reports to Kevin, directly or through someone else
WITH RECURSIVE team AS (
    SELECT employeeid, firstname, managerid
    FROM sales.employees
    WHERE managerid = 2
    UNION ALL
    SELECT e.employeeid, e.firstname, e.managerid
    FROM sales.employees AS e
    INNER JOIN team AS t ON e.managerid = t.employeeid
)
SELECT employeeid, firstname, managerid FROM team;

-- Orders per day for every day of January 2025, including days with no orders (a recursive date series)
WITH RECURSIVE days AS (
    SELECT DATE '2025-01-01' AS day
    UNION ALL
    SELECT day + 1 FROM days WHERE day < DATE '2025-01-31'
)
SELECT d.day, COUNT(o.orderid) AS orders
FROM days AS d
LEFT JOIN sales.orders AS o ON o.orderdate = d.day
GROUP BY d.day
ORDER BY d.day;

-- The same January date series with PostgreSQL's built-in GENERATE_SERIES, no recursion needed
SELECT d::date AS day, COUNT(o.orderid) AS orders
FROM GENERATE_SERIES(DATE '2025-01-01', DATE '2025-01-31', INTERVAL '1 day') AS d
LEFT JOIN sales.orders AS o ON o.orderdate = d::date
GROUP BY d
ORDER BY d;
